1	// Modified from rakazo (Apache-2.0), github.com/elie222/rakazo@912c977
2	import { ChevronRight } from "lucide-react";
3	import { AnimatePresence } from "motion/react";
4	import * as m from "motion/react-m";
5	import { type ReactNode, useState } from "react";
6	import { Collapse } from "@/components/motion/Collapse";
7	import { DISTANCE, DURATION, enterTransition, exitTransition, symmetric } from "@/lib/motion";
8	import { formatToolActivityDuration, toolStepCount } from "@/lib/tool-activity-view";
9	
10	/** Step rows slide in as tools start and out when the live window moves past them. */
11	const stepRow = symmetric({ y: DISTANCE.sm }, DURATION.fast);
12	
13	/** `status` overrides the currentIndex-based icon (nlhack: per-step state from AI SDK tool parts). */
14	export type ToolStep = { label: string; count: number; status?: "running" | "done" | "error" };
15	
16	/** A run's tool steps (rakazo's `steps` message block shape). */
17	export type ToolStepsBlock = { kind: "steps"; steps: ToolStep[]; durationMs?: number };
18	
19	/** Replaces lingui's <Plural>: "#" is substituted with the count. */
20	function plural(n: number, one: string, other: string): string {
21	  return (n === 1 ? one : other).replace("#", String(n));
22	}
23	
24	/** While a run is live, only the most recent steps are listed so a long run does not push the chat down. */
25	export const LIVE_TOOL_STEP_WINDOW = 6;
26	
27	export function ToolSteps({
28	  steps,
29	  currentIndex,
30	  limit,
31	}: {
32	  steps: readonly ToolStep[];
33	  currentIndex?: number;
34	  /** Show only the last `limit` steps, with a count of the earlier ones above them. */
35	  limit?: number;
36	}) {
37	  const hidden = limit !== undefined && steps.length > limit ? steps.length - limit : 0;
38	  const shown = hidden > 0 ? steps.slice(hidden) : steps;
39	  return (
40	    <div className="space-y-0.5" data-testid="tool-rows">
41	      {hidden > 0 ? (
42	        <div className="text-[12px] leading-5 text-muted-foreground" data-testid="tool-rows-hidden">
43	          {plural(hidden, "+# earlier step", "+# earlier steps")}
44	        </div>
45	      ) : null}
46	      <AnimatePresence initial={false}>
47	      {shown.map((step, offset) => {
48	        const index = hidden + offset;
49	        const status = step.status ?? (index === currentIndex ? "running" : "done");
50	        const isCurrent = status === "running";
51	        return (
52	          <m.div
53	            key={index}
54	            variants={stepRow}
55	            initial="hidden"
56	            animate="visible"
57	            exit="hidden"
58	            className="flex min-w-0 items-center gap-2 leading-5"
59	          >
60	            <span
61	              className={`text-[12px] ${
62	                isCurrent ? "text-warning" : status === "error" ? "text-destructive" : "text-success"
63	              }`}
64	              style={{ animation: isCurrent ? "rkPulse 1.2s ease-in-out infinite" : undefined }}
65	            >
66	              {isCurrent ? "◷" : status === "error" ? "✕" : "✓"}
67	            </span>
68	            <span
69	              className={`min-w-0 flex-1 truncate text-[13px] ${
70	                isCurrent ? "text-foreground" : "text-muted-foreground"
71	              }`}
72	              title={step.label}
73	            >
74	              {step.label}
75	              {step.count > 1 ? ` ×${step.count}` : ""}
76	            </span>
77	          </m.div>
78	        );
79	      })}
80	      </AnimatePresence>
81	    </div>
82	  );
83	}
84	
85	/**
86	 * The tool-activity card. It starts open while the run is live and folds when the run
87	 * ends (nlhack: a height-auto Collapse replaces rakazo's <details> so opening and closing
88	 * animate symmetrically). A manual toggle during the run holds until `live` changes.
89	 */
90	export function ToolActivityDisclosure({
91	  live,
92	  stepCount,
93	  durationMs,
94	  children,
95	}: {
96	  live: boolean;
97	  stepCount: number;
98	  durationMs?: number;
99	  children: ReactNode;
100	}) {
101	  const duration = formatToolActivityDuration(durationMs);
102	  const [open, setOpen] = useState(live);
103	  const [wasLive, setWasLive] = useState(live);
104	  if (live !== wasLive) {
105	    // Re-derive from the prop when the run starts or ends (React's "adjust state on prop change").
106	    setWasLive(live);
107	    setOpen(live);
108	  }
109	  return (
110	    <div data-testid="tool-activity" data-live={live || undefined} data-open={open || undefined}>
111	      <button
112	        type="button"
113	        aria-expanded={open}
114	        onClick={() => setOpen((value) => !value)}
115	        className={`flex min-h-6 w-fit cursor-pointer items-center gap-1 rounded-md py-0.5 pe-1.5 text-[13px] font-medium outline-none transition-colors duration-(--motion-fast) ease-(--ease-standard) hover:text-foreground/75 focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background ${
116	          live ? "text-foreground/75" : "text-muted-foreground"
117	        }`}
118	      >
119	        <m.span
120	          aria-hidden
121	          className="inline-flex"
122	          initial={false}
123	          animate={{ rotate: open ? 90 : 0 }}
124	          transition={open ? enterTransition(DURATION.fast) : exitTransition(DURATION.fast)}
125	        >
126	          <ChevronRight size={14} strokeWidth={1.8} />
127	        </m.span>
128	        {live ? (
129	          plural(stepCount, "Working… · # tool", "Working… · # tools")
130	        ) : (
131	          <>
132	            {plural(stepCount, "Done · # tool", "Done · # tools")}
133	            {duration ? ` · ${duration}` : null}
134	          </>
135	        )}
136	      </button>
137	      <Collapse open={open}>
138	        <div className="ms-[7px] mt-0.5 border-s border-border ps-3">{children}</div>
139	      </Collapse>
140	    </div>
141	  );
142	}
143	
144	/**
145	 * A tools-only message: a plain muted line between messages, not a chat bubble.
146	 */
147	export function StandaloneToolActivity({
148	  live,
